def pre(xs):
    if len(xs) < 1:
        return False
    if len(xs) > 6:
        return False
    for x in xs:
        if x < -10:
            return False
        if x > 10:
            return False
    return True

def post(xs, result):
    if len(xs) == 0:
        return False

    best = xs[0]
    cur = xs[0]

    for i in range(1, len(xs)):
        x = xs[i]
        cur = max(x, cur + x)
        best = max(best, cur)

    return result == best
